// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListBooks List books
	// (GET /books)
	ListBooks(w http.ResponseWriter, r *http.Request, params ListBooksParams)
	// UploadBook Upload an EPUB and start its import
	// (POST /books)
	UploadBook(w http.ResponseWriter, r *http.Request)
	// DeleteBook Delete a book with all its data and files
	// (DELETE /books/{bookId})
	DeleteBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetBook Get a book
	// (GET /books/{bookId})
	GetBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// UpdateBook Change the narrator voice, speed or lookahead
	// (PATCH /books/{bookId})
	UpdateBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetAnalysis State of the book's character analysis (or an estimate before it starts)
	// (GET /books/{bookId}/analysis)
	GetAnalysis(w http.ResponseWriter, r *http.Request, bookId BookId)
	// StartAnalysis Start or resume the character analysis
	// (POST /books/{bookId}/analysis)
	StartAnalysis(w http.ResponseWriter, r *http.Request, bookId BookId)
	// PauseAnalysis Pause the character analysis (a running batch finishes first)
	// (POST /books/{bookId}/analysis/pause)
	PauseAnalysis(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetCasting State of the book's voice casting
	// (GET /books/{bookId}/casting)
	GetCasting(w http.ResponseWriter, r *http.Request, bookId BookId)
	// StartCasting Cast voices for the main characters that have none
	// (POST /books/{bookId}/casting)
	StartCasting(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListChapters List a book's chapters in reading order
	// (GET /books/{bookId}/chapters)
	ListChapters(w http.ResponseWriter, r *http.Request, bookId BookId, params ListChaptersParams)
	// ListCharacters A book's characters
	// (GET /books/{bookId}/characters)
	ListCharacters(w http.ResponseWriter, r *http.Request, bookId BookId, params ListCharactersParams)
	// MergeCharacters Merge characters into one (their names become aliases)
	// (POST /books/{bookId}/characters/merge)
	MergeCharacters(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetBookCover The book's cover image
	// (GET /books/{bookId}/cover)
	GetBookCover(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListDownloads The book's M4B downloads, one per volume (or one for the whole book without volumes)
	// (GET /books/{bookId}/downloads)
	ListDownloads(w http.ResponseWriter, r *http.Request, bookId BookId)
	// AssembleDownload Build the M4B of a volume (missing chapters are rendered first)
	// (POST /books/{bookId}/downloads/{volumeId})
	AssembleDownload(w http.ResponseWriter, r *http.Request, bookId BookId, volumeId VolumeId)
	// GetDownloadFile The assembled M4B with chapter markers; supports HTTP range requests
	// (GET /books/{bookId}/downloads/{volumeId}/file)
	GetDownloadFile(w http.ResponseWriter, r *http.Request, bookId BookId, volumeId VolumeId)
	// ExportBook Export the book with its analysis, voices, speakers, edits and pronunciations (zip, without audio)
	// (GET /books/{bookId}/export)
	ExportBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListLexicon The book's pronunciation lexicon
	// (GET /books/{bookId}/lexicon)
	ListLexicon(w http.ResponseWriter, r *http.Request, bookId BookId)
	// CreateLexiconEntry Add a pronunciation (chapters containing the term become outdated)
	// (POST /books/{bookId}/lexicon)
	CreateLexiconEntry(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetProgress The listening position
	// (GET /books/{bookId}/progress)
	GetProgress(w http.ResponseWriter, r *http.Request, bookId BookId)
	// SaveProgress Store the listening position (keeps the lookahead window rendered)
	// (PUT /books/{bookId}/progress)
	SaveProgress(w http.ResponseWriter, r *http.Request, bookId BookId)
	// RenderBookChapters Queue the next chapters without audio for rendering
	// (POST /books/{bookId}/render)
	RenderBookChapters(w http.ResponseWriter, r *http.Request, bookId BookId)
	// DesignBookVoices Design voices for the main characters whose voice was not chosen by hand
	// (POST /books/{bookId}/voice-design)
	DesignBookVoices(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListVolumes List a book's volumes
	// (GET /books/{bookId}/volumes)
	ListVolumes(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetChapter A chapter with its paragraphs and segments
	// (GET /chapters/{chapterId})
	GetChapter(w http.ResponseWriter, r *http.Request, chapterId ChapterId)
	// UpdateChapter Rename a chapter or exclude it from narration
	// (PATCH /chapters/{chapterId})
	UpdateChapter(w http.ResponseWriter, r *http.Request, chapterId ChapterId)
	// StartAttribution Attribute the chapter's quotations to their speakers
	// (POST /chapters/{chapterId}/attribution)
	StartAttribution(w http.ResponseWriter, r *http.Request, chapterId ChapterId)
	// GetChapterAudio The chapter's audio (AAC in MP4); supports HTTP range requests
	// (GET /chapters/{chapterId}/audio)
	GetChapterAudio(w http.ResponseWriter, r *http.Request, chapterId ChapterId, params GetChapterAudioParams)
	// MergeChapterWithNext Append the following chapter to this one
	// (POST /chapters/{chapterId}/merge-next)
	MergeChapterWithNext(w http.ResponseWriter, r *http.Request, chapterId ChapterId)
	// StartPreparation Prepare the chapter for reading aloud
	// (POST /chapters/{chapterId}/preparation)
	StartPreparation(w http.ResponseWriter, r *http.Request, chapterId ChapterId)
	// UpdateQuote Choose the speaker or emotion of a quotation
	// (PATCH /chapters/{chapterId}/quotes/{quoteRef})
	UpdateQuote(w http.ResponseWriter, r *http.Request, chapterId ChapterId, quoteRef int)
	// RenderChapter Queue a chapter for rendering (again)
	// (POST /chapters/{chapterId}/render)
	RenderChapter(w http.ResponseWriter, r *http.Request, chapterId ChapterId, params RenderChapterParams)
	// SplitChapter Start a new chapter at the given paragraph
	// (POST /chapters/{chapterId}/split)
	SplitChapter(w http.ResponseWriter, r *http.Request, chapterId ChapterId)
	// GetChapterTimings When each segment is spoken in the chapter's audio (for reading along)
	// (GET /chapters/{chapterId}/timings)
	GetChapterTimings(w http.ResponseWriter, r *http.Request, chapterId ChapterId, params GetChapterTimingsParams)
	// DeleteCharacter Delete a character (e.g. not a person)
	// (DELETE /characters/{characterId})
	DeleteCharacter(w http.ResponseWriter, r *http.Request, characterId CharacterId)
	// GetCharacter A character with aliases and chapters
	// (GET /characters/{characterId})
	GetCharacter(w http.ResponseWriter, r *http.Request, characterId CharacterId)
	// UpdateCharacter Correct a character (protects it from being overwritten by the analysis)
	// (PATCH /characters/{characterId})
	UpdateCharacter(w http.ResponseWriter, r *http.Request, characterId CharacterId)
	// ListCharacterQuotes Quotes the character speaks in the book (for voice previews)
	// (GET /characters/{characterId}/quotes)
	ListCharacterQuotes(w http.ResponseWriter, r *http.Request, characterId CharacterId, params ListCharacterQuotesParams)
	// SplitCharacter Move aliases of a character to a new character
	// (POST /characters/{characterId}/split)
	SplitCharacter(w http.ResponseWriter, r *http.Request, characterId CharacterId)
	// DesignVoice Design a voice for the character from a description
	// (POST /characters/{characterId}/voice-design)
	DesignVoice(w http.ResponseWriter, r *http.Request, characterId CharacterId)
	// ImportBook Restore an exported book as a new book (the restore runs as a job)
	// (POST /import)
	ImportBook(w http.ResponseWriter, r *http.Request)
	// ListJobs List background jobs, newest first
	// (GET /jobs)
	ListJobs(w http.ResponseWriter, r *http.Request, params ListJobsParams)
	// CancelJob Cancel a queued job
	// (POST /jobs/{jobId}/cancel)
	CancelJob(w http.ResponseWriter, r *http.Request, jobId JobId)
	// RetryJob Queue a failed or canceled job again
	// (POST /jobs/{jobId}/retry)
	RetryJob(w http.ResponseWriter, r *http.Request, jobId JobId)
	// DeleteLexiconEntry Remove a pronunciation
	// (DELETE /lexicon/{entryId})
	DeleteLexiconEntry(w http.ResponseWriter, r *http.Request, entryId int64)
	// UpdateLexiconEntry Change a pronunciation
	// (PATCH /lexicon/{entryId})
	UpdateLexiconEntry(w http.ResponseWriter, r *http.Request, entryId int64)
	// ListLLMModels Models offered by an OpenAI-compatible server (GET /models)
	// (POST /llm/models)
	ListLLMModels(w http.ResponseWriter, r *http.Request)
	// ListLLMProviders LLM providers in the order they are tried, with quota usage
	// (GET /llm/providers)
	ListLLMProviders(w http.ResponseWriter, r *http.Request)
	// CreateLLMProvider Add an LLM provider
	// (POST /llm/providers)
	CreateLLMProvider(w http.ResponseWriter, r *http.Request)
	// DeleteLLMProvider Remove an LLM provider and its usage history
	// (DELETE /llm/providers/{providerId})
	DeleteLLMProvider(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// UpdateLLMProvider Change an LLM provider (providers from the Helm values are read-only)
	// (PATCH /llm/providers/{providerId})
	UpdateLLMProvider(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// TestLLMProvider Send a small structured-output request to the provider and check the answer
	// (POST /llm/providers/{providerId}/test)
	TestLLMProvider(w http.ResponseWriter, r *http.Request, providerId ProviderId)
	// GetMe The signed-in user
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetSettings Settings of this instance
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Change settings of this instance
	// (PATCH /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// GetSystemInfo Version, database and TTS status
	// (GET /system)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// ListTTSEngines The speech engines configured besides Kokoro, with their voices
	// (GET /tts/engines)
	ListTTSEngines(w http.ResponseWriter, r *http.Request)
	// ListVoices The voice catalogue, reconciled with the voices the TTS server offers
	// (GET /voices)
	ListVoices(w http.ResponseWriter, r *http.Request)
	// PreviewVoice Speak a sample text with a voice
	// (POST /voices/preview)
	PreviewVoice(w http.ResponseWriter, r *http.Request)
}

